String cbText(BuildContext context, String key, {Map<String, String> args = const {}}) {
  var lang = Localizations.localeOf(context).languageCode;
  if (lang == 'zgh') lang = 'fr';
  var s = _t[key]?[lang] ?? _t[key]?['en'] ?? key;
  args.forEach((k, v) => s = s.replaceAll('{$k}', v));
  return s;
}
